L19_1.m_Pos = "L"
L19_1.m_Talk_KOREA = "엄청 빠르게 도망다니느라 몇 년째 못 잡아서 현상금도 꽤 높은 걸로 아는데."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "逃げ足が速くて何年も捕まえられなかったから懸賞金がけっこう高かったような。"
L19_1.m_Talk_ENG = "It's so nimble and quick that no one's been able to catch it for years. I'm pretty sure its bounty is pretty high."
L19_1.m_Talk_TWN = "他的賞金很高的，但因為跑得太快，好幾年沒人能抓到他。"
L19_1.m_Talk_THA = "มันว่องไวและรวดเร็วจนไม่มีใครสามารถจับมันได้มานานหลายปี ฉันค่อนข้างมั่นใจว่าค่าหัวนั้นสูง"
L19_1.m_Talk_VTN = "Nó nhanh nhẹn và lanh lợi đến mức suốt bao năm qua không ai có thể bắt được. Tôi khá chắc tiền thưởng rất cao."
L19_1.m_Talk_SCN = "这家伙的赏金可是很高的，因为跑得太快，好几年都没人能抓到它。"
L19_1.m_Talk_DEU = "It's so nimble and quick that no one's been able to catch it for years. I'm pretty sure its bounty is pretty high."
L19_1.m_Talk_FRA = "It's so nimble and quick that no one's been able to catch it for years. I'm pretty sure its bounty is pretty high."
