L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "船長！　今死にかけているのに懸賞金のことを考えてる場合ですか！？"
L20_1.m_Talk_ENG = "Captain! I'm dying here, and you're thinking about bounties?!"
L20_1.m_Talk_TWN = "船長！現在是考慮賞金的時候嗎？我都快沒命咧？"
L20_1.m_Talk_THA = "กัปตัน! ฉันกำลังจะตายที่นี่ และคุณกำลังคิดถึงเรื่องค่าหัวเหรอ?!"
L20_1.m_Talk_VTN = "Thuyền trưởng! Tôi sắp chết ở đây mà cô đang nghĩ về tiền thưởng?!"
L20_1.m_Talk_SCN = "船长！现在是考虑赏金的时候吗，我们就快死了耶？"
L20_1.m_Talk_DEU = "Captain! I'm dying here, and you're thinking about bounties?!"
