L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "ソーニャがあれ捕まえて食べてください！　海産物は全部好きでしょう！"
L21_1.m_Talk_ENG = "Sonya, eat that thing! You like seafood, right?!"
L21_1.m_Talk_TWN = "索妮雅，把他抓來吃吧！你不是喜歡任何海鮮嗎！"
L21_1.m_Talk_THA = "ซอนย่า กินนั่นซะ! คุณชอบอาหารทะเลใช่ไหม!"
L21_1.m_Talk_VTN = "Sonya, ăn cái đó đi! Cô thích hải sản phải không?"
L21_1.m_Talk_SCN = "索尼娅，快把它抓来吃掉吧！你不是喜欢海鲜吗！"
L21_1.m_Talk_DEU = "Sonya, eat that thing! You like seafood, right?!"
L21_1.m_Talk_FRA = "Sonya, eat that thing! You like seafood, right?!"
