L6_1 = "FX_CUTSCEN_SEAWAVE"
L5_1.m_StartFXSoundName = L6_1
L5_1.m_CharStrID = "HUNTER_FRONTBAY_NULL_SEVERAL"
L5_1.m_Pos = "L"
L6_1 = "끝이군. 아직 회항하지 못한 녀석들은 안타깝게 됐어."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "終わりだな。まだ戻ってこれないやつらは残念だ。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "That's it. Too bad for the ones who couldn't sail back in time."
L5_1.m_Talk_ENG = L6_1
L6_1 = "都結束了，只能犧牲那些來不及返港的人了。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "แค่นั้นแหละ. น่าเสียดายสำหรับคนที่ไม่สามารถย้อนเวลากลับไปได้"
L5_1.m_Talk_THA = L6_1
L6_1 = "Đó là nó. Thật tiếc cho những người không thể chèo thuyền quay ngược thời gian."
L5_1.m_Talk_VTN = L6_1
L6_1 = "结束了。那些还没返航的人，只能为他们哀悼了。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "That's it. Too bad for the ones who couldn't sail back in time."
L5_1.m_Talk_DEU = L6_1
L6_1 = "That's it. Too bad for the ones who couldn't sail back in time."
L5_1.m_Talk_FRA = L6_1
