L7_1 = "FRONTBAY_ACT1_INTERLUDE1@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 5900113
L6_1.m_CutScenStrID = "FRONTBAY_ACT1_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "HUNTER_FRONTBAY_NULL_NEWBIE"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "검은 범람에서 살아돌아온 생존자는 지금까지 없었나?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "黒い氾濫から生きて帰ってきた生存者って今まであったか？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Were there no survivors of the Black Flood before?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "從來沒有人能從黑色洪災中倖存下來嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ไม่เคยมีผู้รอดชีวิตจากเหตุการณ์น้ำท่วมครั้งนี้มาก่อนเลยหรือ?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Trước đây không có người sống sót sau trận Lũ Đen?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "从来没有人能从黑色洪灾中幸存下来吗？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Were there no survivors of the Black Flood before?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Were there no survivors of the Black Flood before?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "FRONTBAY_ACT1_INTERLUDE1@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 5900113
L7_1.m_CutScenStrID = "FRONTBAY_ACT1_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "HUNTER_FRONTBAY_NULL_SEVERAL"
L7_1.m_Pos = "L"
L8_1 = "검은 범람이 위험한 건 소금물이 아니라 군단 규모의 침식체들 때문이야. 거기에 휩쓸리면 가망이 없다고 봐야지."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "黒い氾濫が危ないのは塩水じゃなく、軍団規模の侵食体なんだ。あそこに巻き込まれちゃ後はないと思った方がいいな。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "The saltwater isn't the dangerous part of the Black Flood, it's the horde of C.O.s. You're practically already dead if you get swept up in that."
L7_1.m_Talk_ENG = L8_1
L8_1 = "黑色洪災之所以危險，不是因為海水，而是大規模的侵蝕體。若是被捲入其中，將會萬劫不復。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "น้ำเค็มไม่ใช่ส่วนที่เป็นอันตรายของเหตุการณ์น้ำท่วมใหญ่\nแต่เป็นฝูงวัตถุคอร์รัปต์ คุณเกือบตายแล้วถ้าคุณถูกพัดเข้าไป"
L7_1.m_Talk_THA = L8_1
L8_1 = "Nước mặn không phải là phần nguy hiểm của Trận Lũ Đen, mà là đám V.T.A.M.. nếu bị cuốn vào đó thì coi như đã chết ."
L7_1.m_Talk_VTN = L8_1
L8_1 = "黑色洪灾之所以危险，不是因为海水，而是大规模的侵蚀体。如果被卷进去了，再多人也不够侵蚀体啃的。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "The saltwater isn't the dangerous part of the Black Flood, it's the horde of C.O.s. You're practically already dead if you get swept up in that."
L7_1.m_Talk_DEU = L8_1
L8_1 = "The saltwater isn't the dangerous part of the Black Flood, it's the horde of C.O.s. You're practically already dead if you get swept up in that."
L7_1.m_Talk_FRA = L8_1
