L11_1 = "HUNTER_FRONTBAY_NULL_NEWBIE"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "저 해일 꼭대기에 있는 거… 혹시 배인가?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "あの津波のてっぺんにあるのって……もしかして船か？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "That thing on top of the tidal wave... Is that a ship?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "海嘯最上面的東西……是船嗎？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "สิ่งนั้นอยู่เหนือคลื่น... นั่นเรือเหรอ?"
L10_1.m_Talk_THA = L11_1
L11_1 = "Thứ nằm trên ngọn sóng thủy triều... Đó có phải là một con tàu không?"
L10_1.m_Talk_VTN = L11_1
L11_1 = "海浪最上面的那个东西……是船吗？"
L10_1.m_Talk_SCN = L11_1
