L11_1.m_Pos = "L"
L12_1 = "뭐? 배가 무슨 서핑보드도 아니고 그런 게 가능할 리가…"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "は？　サーブボードでもあるまいし、船でそんなことできるはずが……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Huh? Ships can't surf, that's not possible–"
L11_1.m_Talk_ENG = L12_1
L12_1 = "什麼？船又不是衝浪板，怎麼可能？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ฮะ? เรือไม่สามารถโต้คลื่นได้ นั่นเป็นไปไม่ได้–"
L11_1.m_Talk_THA = L12_1
L12_1 = "Huh? Tàu không thể lướt được, điều đó là không thể–"
L11_1.m_Talk_VTN = L12_1
L12_1 = "什么？船又不是冲浪板，怎么可能？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Huh? Ships can't surf, that's not possible–"
