L13_1 = "It's true! A ship is riding the waves!"
L12_1.m_Talk_ENG = L13_1
L13_1 = "是真的！那艘船正在浪頭上！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "มันเป็นความจริง! เรือกำลังโต้คลื่น!"
L12_1.m_Talk_THA = L13_1
L13_1 = "Đúng rồi! Một con tàu đang cưỡi sóng!"
L12_1.m_Talk_VTN = L13_1
L13_1 = "是真的！那艘船正驶在浪头上！"
L12_1.m_Talk_SCN = L13_1
L13_1 = "It's true! A ship is riding the waves!"
