L25_1.m_Talk_SCN = L26_1
L26_1 = "Kya hah hah! Why would you stop? That wasn't a part of my plan!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Kya hah hah! Why would you stop? That wasn't a part of my plan!"
