L28_1 = "죽으면 선장님 원망할 거예요! 물귀신이 돼서 평생 괴롭힐 거라고요!"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "死んだら船長を恨みますよ！　お化けになって死ぬまで苦しめますよ！"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I'm going to curse you if I die! I'm going to become a ghost and haunt you for the rest of your life!"
L27_1.m_Talk_ENG = L28_1
L28_1 = "要是我死了，我做鬼也不會放過船長！我會變成水鬼一輩子折磨你！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ฉันจะสาปแช่งคุณถ้าฉันตาย! ฉันจะกลายเป็นผีและหลอกหลอนคุณไปตลอดชีวิต!"
L27_1.m_Talk_THA = L28_1
L28_1 = "Tôi sẽ nguyền rủa cô nếu tôi chết! Tôi sẽ trở thành một hồn ma và ám ảnh cô đến hết cuộc đời!"
L27_1.m_Talk_VTN = L28_1
L28_1 = "如果我死了，我做鬼都不会放过你的，船长！我会变成水鬼一辈子缠着你！"
L27_1.m_Talk_SCN = L28_1
L28_1 = "I'm going to curse you if I die! I'm going to become a ghost and haunt you for the rest of your life!"
L27_1.m_Talk_DEU = L28_1
L28_1 = "I'm going to curse you if I die! I'm going to become a ghost and haunt you for the rest of your life!"
