L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "L_M_I"
L34_1 = "저건…? 샤크스 해적단의 깃발이잖아?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "あれは……？　シャークス海賊団の旗じゃないか？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Isn't that...? The flag of the Sharks Pirates?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "那是…？那不是大白鯊海盜團的旗幟嗎？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "นั่นคือ...? นั่นคือธงของฉลาม"
L33_1.m_Talk_THA = L34_1
L34_1 = "Đó là...? Đó là lá cờ của Cá Mập."
L33_1.m_Talk_VTN = L34_1
L34_1 = "那是……？那不是大白鲨海盗团的旗帜吗？"
