L34_1.m_CharStrID = L35_1
L35_1 = "R_M_I"
L34_1.m_Pos = L35_1
L35_1 = "드라코? 부하들을 탈옥시켰단 소식은 들었지만, 하필 이럴 때 바다로 나가 있었던 건가?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ドラコ？　部下たちを脱獄させたとは聞いたが、まさかよりによってこんな時に海に出ていたのか？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Dracasia? I heard she broke out her crew members, but what a bad timing to be out at sea."
L34_1.m_Talk_ENG = L35_1
L35_1 = "德拉克？我聽說她幫助手下逃獄，怎麼會偏偏挑這種時候出海？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ดราคาเซีย? ฉันได้ยินมาว่าเธอหนีไปพร้อมกับลูกน้องของเธอ แต่ช่างเป็นช่วงเวลาที่ไม่ดีเลยที่ต้องออกทะเล"
L34_1.m_Talk_THA = L35_1
L35_1 = "Dracasia? Tôi nghe nói cô ta đã trốn thoát cùng cấp dưới của mình, nhưng ra khơi không đúng lúc rồi."
L34_1.m_Talk_VTN = L35_1
L35_1 = "德拉蔻？听说她为了手下劫狱，这个时候出海可不是什么好时机？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Dracasia? I heard she broke out her crew members, but what a bad timing to be out at sea."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Dracasia? I heard she broke out her crew members, but what a bad timing to be out at sea."
