L37_1.m_CharStrID = "HUNTER_FRONTBAY_NULL_SEVERAL"
L38_1 = "R_M_I"
L37_1.m_Pos = L38_1
L38_1 = "뭐야? 범법자들이 탄 해적선이었어?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "何？　犯罪者が乗っている海賊船だったのか？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Huh? It's a pirate ship holding criminals?"
L37_1.m_Talk_ENG = L38_1
L38_1 = "什麼？海盜船上有罪犯？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ฮะ? มันเป็นเรือโจรสลัดที่จับกุมอาชญากรเหรอ?"
L37_1.m_Talk_THA = L38_1
L38_1 = "Huh? Đó là một con tàu hải tặc đang giam giữ tội phạm?"
L37_1.m_Talk_VTN = L38_1
L38_1 = "呃？原来是罪犯开着的海盗船？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Huh? It's a pirate ship holding criminals?"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Huh? It's a pirate ship holding criminals?"
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "FRONTBAY_ACT1_INTERLUDE1@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 5900113
L38_1.m_CutScenStrID = "FRONTBAY_ACT1_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "HUNTER_FRONTBAY_NULL_SEVERAL"
L38_1.m_Pos = "L_M_I"
L39_1 = "잘 찍어 둬. 침식체한테 끌려다니다 격벽에 들이받는 멍청한 해적의 최후는 영상으로 남겨둬야지."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ちゃんと撮っておけ。侵食体に引っ張られ隔壁にぶつかるバカな海賊の最期は動画で残さなきゃな。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Start filming. We should leave a video of what happens to dumb pirates who get dragged by a C.O. before they crash into the bulwark."
L38_1.m_Talk_ENG = L39_1
L39_1 = "快拍下來，看看這些被侵蝕體拖去撞牆的愚蠢海盜，必須替她們留下最後的影像。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เริ่มถ่ายทำ เราควรทิ้งวิดีโอเกี่ยวกับสิ่งที่เกิดขึ้นกับโจรสลัดโง่ที่ถูกวัตถุคอร์รัปต์ลากก่อนที่พวกเขาจะชนกำแพงมหาสมุทร"
L38_1.m_Talk_THA = L39_1
L39_1 = "Bắt đầu quay phim. Chúng ta nên quay một đoạn video những gì xảy ra với những tên hải tặc ngu ngốc bị V.T.A.M. kéo đi trước khi chúng đâm vào bức tường đại dương."
L38_1.m_Talk_VTN = L39_1
L39_1 = "快录下来——被侵蚀体拖着撞向隔离墙，这就是愚蠢海盗们的最后结局。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Start filming. We should leave a video of what happens to dumb pirates who get dragged by a C.O. before they crash into the bulwark."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Start filming. We should leave a video of what happens to dumb pirates who get dragged by a C.O. before they crash into the bulwark."
L38_1.m_Talk_FRA = L39_1
