L51_1 = "GUARD_FRONTBAY_CAP_ADMIN"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "…드라코와 그 일당들인가? 격벽 일꾼이 탈출한 죄가 얼마나 무거운진 알고 있겠지?"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "……ドラコとその仲間か？　隔壁人夫の脱獄罪がどれだけ重いのかは知っているな？"
L50_1.m_Talk_JPN = L51_1
L51_1 = "...Dracasia and her gang? I'm sure you're well aware of the consequences of a bulwark laborer escaping."
L50_1.m_Talk_ENG = L51_1
L51_1 = "…你們是德拉克和她的手下嗎？你們應該知道隔離牆工人逃跑的罪有多重吧？"
L50_1.m_Talk_TWN = L51_1
L51_1 = "...ดราคาเซียและแก๊งค์ของเธอเหรอ? ผมแน่ใจว่าคุณคง\nทราบดีถึงผลที่ตามมาของการหลบหนีของคนงานในกำแพงมหาสมุทร"
L50_1.m_Talk_THA = L51_1
L51_1 = "...Dracasia và đồng bọn? Tôi chắc rằng các người nhận thức rõ hậu quả của việc người lao động ở tường đại dương trốn thoát."
L50_1.m_Talk_VTN = L51_1
L51_1 = "德拉蔻和她的手下……我想你们也十分清楚逃避隔离墙劳役的后果吧？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "...Dracasia and her gang? I'm sure you're well aware of the consequences of a bulwark laborer escaping."
L50_1.m_Talk_DEU = L51_1
L51_1 = "...Dracasia and her gang? I'm sure you're well aware of the consequences of a bulwark laborer escaping."
L50_1.m_Talk_FRA = L51_1
