L3_1.m_Talk_THA = L4_1
L4_1 = "Thực ra tôi đang trên đường trở về sau khi giết một V.T.A.M. với mức tiền thưởng cao."
L3_1.m_Talk_VTN = L4_1
L4_1 = "不过我们正好抓了一个一级悬赏的侵蚀体。"
