L5_1.m_Talk_THA = L6_1
L6_1 = "Cô có thể cân bằng số tiền thưởng trên đầu của cô với tiền thưởng của người khác! Đó là luật của Vịnh Trước!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "可以用别人的悬赏抵消自己头上的悬赏！这就是前湾的规矩！"
