L14_1.m_Talk_TWN = L15_1
L15_1 = "อาชญากรที่ต้องการตัวจะถูกส่งเข้าคุกโดยไม่มีการพิจารณาคดี นั่นก็เป็นกฎในฟรอนต์เบย์เช่นกัน"
L14_1.m_Talk_THA = L15_1
L15_1 = "Những tội phạm bị truy nã sẽ bị đưa vào tù mà không cần xét xử. Đó cũng là quy định ở Vịnh Trước."
L14_1.m_Talk_VTN = L15_1
