L15_1.m_Talk_TWN = L16_1
L16_1 = "อย่างไรก็ตาม คุณจะสามารถออกไปได้หลังจากทำงานเป็นคนงานกำแพงมหาสมุทรมา 3 ปี"
L15_1.m_Talk_THA = L16_1
L16_1 = "Tuy nhiên, cô sẽ có thể ra ngoài sau 3 năm làm công nhân xây tường chắn biển."
