L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "그럴 리가. 상식인이라면 출입금지 해역의 아무것도 없는 섬에 발을 들이진 않겠지."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "そんなわけあるか。常識人なら立入禁止海域の何もない島には足を運ばないな。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Of course not. No one with common sense would ever set foot on an island full of nothing in the middle of restricted waters."
L47_1.m_Talk_ENG = L48_1
L48_1 = "當然沒有，任何有常識的人，都不會踏入那座禁止出入的無人荒島。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ไม่แน่นอน ไม่มีใครที่มีสามัญสำนึกจะก้าวเท้าไปบนเกาะที่เต็มไปด้วยความว่างเปล่ากลางผืนน้ำที่ถูกจำกัด"
L47_1.m_Talk_THA = L48_1
L48_1 = "Dĩ nhiên là không. Không ai bình thường lại có thể đặt chân lên một hòn đảo chẳng có gì giữa vùng biển bị hạn chế."
L47_1.m_Talk_VTN = L48_1
L48_1 = "当然没有，任何有常识的人，都不会踏进那座禁区水域的荒岛。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Of course not. No one with common sense would ever set foot on an island full of nothing in the middle of restricted waters."
