L48_1.m_Pos = "C"
L49_1 = "거기 절벽 끝에서 바라보는 일출이 끝내주게 낭만적이거든."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "あそこの崖っぷちで見る日の出が凄くロアンチックでさ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "The view of the sunset from that island is a frickin' dream."
L48_1.m_Talk_ENG = L49_1
L49_1 = "可是在那裡的懸崖上看日出特別浪漫。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "วิวพระอาทิตย์ตกจากเกาะนั้นช่างฝันเหลือเกิน"
L48_1.m_Talk_THA = L49_1
L49_1 = "Cảnh hoàng hôn từ hòn đảo đó là một giấc mơ kỳ lạ."
L48_1.m_Talk_VTN = L49_1
L49_1 = "可在那里的悬崖绝壁上看到的日出，特别的浪漫。"
