L5_1.m_Talk_JPN = L6_1
L6_1 = "Aww, you must feel so upset to just let us go after running all the way here!"
L5_1.m_Talk_ENG = L6_1
L6_1 = "出動這麼多人力來抓我們，結果卻空手而歸，一定很嘔吧～"
L5_1.m_Talk_TWN = L6_1
L6_1 = "อุ๊ย คุณคงจะเสียใจมากสินะที่วิ่งมาทางนี้ให้เราวิ่งไป!"
L5_1.m_Talk_THA = L6_1
L6_1 = "Aww, mọi người chắc hẳn khó chịu lắm khi để chúng tôi đi sau khi chạy đến tận đây!"
L5_1.m_Talk_VTN = L6_1
L6_1 = "辛辛苦苦追过来，结果却空手而归，要气死了气死了~"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Aww, you must feel so upset to just let us go after running all the way here!"
